-- Linking banks through Enable Banking (src/lib/banking). Hand-written additions to what drizzle-kit made.
-- Neither table ever holds the application's private key or a signed token; the session id is kept server side only.

-- Same access as every other table: only the app role, only a user's own rows.
GRANT SELECT, INSERT, UPDATE, DELETE ON "bank_connections" TO kasboek_app;
--> statement-breakpoint
GRANT USAGE, SELECT ON SEQUENCE "bank_connections_id_seq" TO kasboek_app;
--> statement-breakpoint
CREATE POLICY tenant ON "bank_connections" FOR ALL TO kasboek_app USING (user_id = (SELECT app.uid())) WITH CHECK (user_id = (SELECT app.uid()));
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "bank_links" TO kasboek_app;
--> statement-breakpoint
GRANT USAGE, SELECT ON SEQUENCE "bank_links_id_seq" TO kasboek_app;
--> statement-breakpoint
CREATE POLICY tenant ON "bank_links" FOR ALL TO kasboek_app USING (user_id = (SELECT app.uid())) WITH CHECK (user_id = (SELECT app.uid()));
--> statement-breakpoint

-- Supabase hands new tables to its API roles by default; take it away again (see 0002).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon')
     AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON "bank_connections" FROM anon, authenticated;
    REVOKE ALL ON SEQUENCE "bank_connections_id_seq" FROM anon, authenticated;
    REVOKE ALL ON "bank_links" FROM anon, authenticated;
    REVOKE ALL ON SEQUENCE "bank_links_id_seq" FROM anon, authenticated;
  END IF;
END
$$;
